-- Staybnb seed (idempotent: wipes listing data, keeps users)
begin;
delete from public.wishlists; delete from public.bookings; delete from public.reviews; delete from public.listing_images; delete from public.listings;
insert into public.listings (id,title,description,city,country,lat,lng,price_per_night,cleaning_fee,max_guests,bedrooms,beds,baths,category,amenities,rating,review_count,host_name,host_avatar) values
