-- Images: 1 exterior + 3 interiors + 1 scenery per listing (all URLs verified HTTP 200)
with ext as (select array['1564013799919-ab600027ffc6','1568605114967-8130f3a36994','1570129477492-45c003edd2be','1512917774080-9991f1c4c750','1600596542815-ffad4c1539a9','1600585154340-be6161a56a0c','1613490493576-7fde63acd811','1580587771525-78b9dba3b914','1613977257363-707ba9348227','1449844908441-8829872d2607','1510798831971-661eb04b3739','1542718610-a1d656d1884c','1499793983690-e29da59ef1c2','1520250497591-112f2f40a3f4','1571896349842-33c89424de2d','1582719478250-c89cae4dc85b','1566073771259-6a8506099945','1551882547-ff40c63fe5fa'] a),
int as (select array['1502672260266-1c1ef2d93688','1522708323590-d24dbb6b0267','1493809842364-78817add7ffb','1505693416388-ac5ce068fe85','1484154218962-a197022b5858','1556909114-f6e7ad7d3136','1560448204-e02f11c3d0e2','1615880484746-a134be9a6ecf','1600607687939-ce8a6c25118c','1600566753190-17f0baa2a6c3','1586023492125-27b2c045efd7','1615529182904-14819c35db37'] a),
sce as (select array['1507525428034-b723cf961d3e','1596394516093-501ba68a0ba6','1537996194471-e657df975ab4','1570077188670-e3a8d69ac5ff','1533105079780-92b9be482077','1502602898657-3e91760cbb34','1493976040374-85c8e12f0c0e','1520483601560-389dff434fdf','1464822759023-fed622ff2c3b','1506905925346-21bda4d32df4','1439066615861-d1af74d74000','1501785888041-af3ef285b470','1470770841072-f978cf4d019e','1580060839134-75a5edca2e99','1523217582562-09d0def993a6','1494526585095-c41746248156','1505843513577-22bb7d21e455','1472214103451-9374bd1c798e'] a),
l as (select id, (row_number() over (order by created_at, title))::int - 1 as n from public.listings)
insert into public.listing_images (listing_id, url, position)
select l.id, 'https://images.unsplash.com/photo-' || pick.pid || '?w=1200&q=80', pick.pos
from l, ext, int, sce,
lateral (values
  (0, ext.a[1 + l.n % 18]),
  (1, int.a[1 + (l.n * 5) % 12]),
  (2, int.a[1 + (l.n * 5 + 3) % 12]),
  (3, int.a[1 + (l.n * 5 + 7) % 12]),
  (4, sce.a[1 + (l.n * 7) % 18])
) as pick(pos, pid)
where pick.pos < 4 or l.n % 3 <> 0;  -- 4 or 5 images each

-- Reviews: 3-6 per listing
with t(i, rating, comment) as (values
 (0,5,'Absolutely stunning place. Even better than the photos and the host was incredibly responsive.'),
 (1,5,'One of the best stays we''ve ever had. Spotless, comfortable, and an unbeatable location.'),
 (2,4,'Lovely home with great amenities. A couple of small things to fix but we''d happily return.'),
 (3,5,'Perfect for our family trip. The kids loved it and we didn''t want to leave.'),
 (4,5,'Beautifully designed and so peaceful. Check-in was seamless.'),
 (5,4,'Great value and the views were incredible. Beds were very comfortable.'),
 (6,5,'The host thought of everything. Highly recommend for a special getaway.')),
a(j, name, face) as (values
 (0,'James Carter','1506794778202-cad84cf45f1d'),(1,'Priya Patel','1544005313-94ddf0286df2'),(2,'Hannah Schmidt','1438761681033-6461ffad8d80'),
 (3,'Tom Becker','1500648767791-00dcc994a43e'),(4,'Aisha Rahman','1534528741775-53994a69daeb'),(5,'Chloe Martin','1494790108377-be9c29b29330'),
 (6,'Liam O''Brien','1507003211169-0a1dd7228f2d'),(7,'Yuki Sato','1517841905240-472988babdf9'),(8,'Isabella Costa','1539571696357-5a69c17a67c6'),
 (9,'Noah Williams','1472099645785-5658abf4ff4e')),
l as (select id, (row_number() over (order by created_at, title))::int - 1 as n from public.listings),
k as (select l.id, l.n, g.k from l, generate_series(0, 2 + (l.n % 4)) g(k))
insert into public.reviews (listing_id, author_name, author_avatar, rating, comment, created_at)
select k.id, a.name, 'https://images.unsplash.com/photo-' || a.face || '?w=200&h=200&fit=crop&q=80', t.rating, t.comment,
       now() - make_interval(days => 5 + ((k.n * 37 + k.k * 53) % 400))
from k join t on t.i = (k.n + k.k * 3) % 7 join a on a.j = (k.n * 3 + k.k) % 10;

-- Sync rating/review_count with reviews (clamped to 4.5-5.0)
update public.listings l set review_count = r.c, rating = greatest(4.5, least(5.0, round(r.avg, 2)))
from (select listing_id, count(*) c, avg(rating) avg from public.reviews group by listing_id) r
where r.listing_id = l.id;

-- Demo guest user (demo@staybnb.test / Demo1234!)
do $$
declare uid uuid := '11111111-1111-4111-8111-111111111111';
begin
  if not exists (select 1 from auth.users where email='demo@staybnb.test') then
    insert into auth.users (instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,recovery_token,email_change,email_change_token_new)
    values ('00000000-0000-0000-0000-000000000000',uid,'authenticated','authenticated','demo@staybnb.test',extensions.crypt('Demo1234!',extensions.gen_salt('bf')),now(),'{"provider":"email","providers":["email"]}','{"full_name":"Demo Guest"}',now(),now(),'','','','');
    insert into auth.identities (id,user_id,provider_id,identity_data,provider,last_sign_in_at,created_at,updated_at)
    values (gen_random_uuid(),uid,uid::text,jsonb_build_object('sub',uid::text,'email','demo@staybnb.test','email_verified',true),'email',now(),now(),now());
  end if;
end $$;
commit;
